def git_run(root: Path, *args: str) -> tuple[int, str]:
    """작업 폴더에서 git 을 실행한다(표준출력+오류를 합쳐 돌려준다)."""
    try:
        proc = subprocess.run(
            ["git", *args],
            cwd=str(root),
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError as exc:
        return 1, str(exc)
    out = (proc.stdout or "") + (proc.stderr or "")
    return proc.returncode, out.strip()


def history_sync_paths(root: Path) -> list[str]:
    """커밋 대상(대화 기록·요약)만 추린다. 다른 변경은 건드리지 않는다."""
    rel = os.path.relpath(HISTORY_BASE, root)
    if rel.startswith(".."):
        return []
    return [rel]


